from __future__ import print_function

import functools
import time

def timeit(f):
  @functools.wraps(f)
  def wrapper(*args, **kwargs):
    start = time.time()
    result = f(*args, **kwargs)
    end = time.time()
    elapsed = end - start
    print("%s Elapsed Time: %s Seconds" % (f.__name__, elapsed))
    return result
  return wrapper

