public class TemperatureConverter
{
    /// <summary>
    /// Map a temperature from Celsius to Fahrenheit.
    /// </summary>
    /// <param name="celsius">The temperature in degrees Celsius.</param>
    /// <returns>The temperature in degrees Fahrenheit.</returns>
    public double FToC(double celsius)
    {
        return (celsius * 1.8) + 32;
    }

    /// <summary>
    /// Map a temperature from Fahrenheit to Celsius.
    /// </summary>
    /// <param name="fahrenheit">The temperature in degrees Fahrenheit.</param>
    /// <returns>The temperature in degrees Celsius.</returns>
    public double CToF(double fahrenheit)
    {
        return (fahrenheit - 32) / 1.8;
    }

    /// <summary>
    /// Valid cases for mapping a known temperature to a different scale.
    /// </summary>
    /// <param name="actual">The temperature.</param>
    /// <param name="expectedC">The expected result in degrees Celsius.</param>
    /// <param name="expectedF">The expected result in degrees Fahrenheit.</param>
    public static void TestValidCases(double actual, double expectedC, double expectedF)
    {
        TemperatureConverter converter = new TemperatureConverter();

        double convertedCelsius = converter.CToF(actual);
        Assert.AreEqual(expectedC, convertedCelsius);

        double convertedFahrenheit = converter.FToC(actual);
        Assert.AreEqual(expectedF, convertedFahrenheit);
    }

