        Assert.AreNotEqual(expectedC, convertedCelsius);

        double convertedFahrenheit = converter.FToC(actual);
        Assert.AreNotEqual(expectedF, convertedFahrenheit);
    }

    /// <summary>
    /// Test negative and zero values for converting between Celsius and Fahrenheit.
    /// </summary>
    public static void TestZeroAndNegativeValues()
